def canonicalEquatorBoundaryPoint (v : sphere (0 : V) 1) (n : ℕ)
    (hdim : Module.finrank ℝ V = n + 3) (z : EquatorSphere v) : SimplexBoundary n :=
  (simplexBoundarySphereHomeomorph n).symm (equatorStandardSphereHomeomorph v (n + 1) hdim z)

